Tôi đã thêm CSS để căn giữa bố cục, tạo khoảng cách (padding/margin) và làm nổi bật các khu vực thao tác bằng màu xanh và màu đỏ, đồng thời loại bỏ các phần tử thừa như Login/Register.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Todo List</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f4f7f6;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
        }
        .container {
            background: white;
            padding: 2rem;
            border-radius: 12px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            width: 90%;
            max-width: 400px;
            text-align: center;
        }
        h1 { color: #333; margin-bottom: 10px; }
        h2 { color: #2c3e50; margin-top: 25px; }
        .todo-list {
            list-style: none;
            padding: 0;
            margin: 0;
            display: flex;
            justify-content: center;
            gap: 20px;
        }
        .todo-item {
            padding: 15px;
            background-color: #7f8c8d;
            border-left: 5px solid #007bff;
            border-radius: 4px;
            font-size: 14px;
            transition: background 0.3s;
        }
        .todo-item:hover { background-color: #0056b3; }
        .todo-button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            background-color: #007bff;
            color: white;
            border: none;
            border-radius: 6px;
            font-weight: bold;
            transition: background 0.2s;
        }
        .todo-button:hover { background-color: #0056b3; }
        .todo-description { margin-left: 20px; color: #666; }
    </style>
</head>
<body>
    <div class="container">
        <h1>Todo List</h1>
        <div class="todo-list">
            <div class="todo-item">Task 1: Completed</div>
            <div class="todo-item">Task 2: Waiting</div>
            <div class="todo-item">Task 3: Done</div>
            <div class="todo-item">Task 4: Unknown</div>
        </div>
        <button onclick="removeTasks()">Clear All (Hoàn thành)</button>
        <button onclick="addTask()">Add Task</button>
    </div>

    <script>
        function removeTasks() {
            const list = document.getElementById('todo-list');
            if (list.classList.contains('item-hidden')) return;
            list.classList.remove('item-hidden');
        }

        function addTask() {
            const list = document.getElementById('todo-list');
            if (!list.classList.contains('item-added')) {
                list.classList.add('item-added');
                const item = document.createElement('div');
                item.innerHTML = '<button onclick="updateTaskList()">Update List</button>' +
                       '<h2 style="color:red;">Task Summary</h2>' +
                       '<p style="color:green;">Completed (%): %</p>' +
                       '<p style="color:red;">Unknown (%): <span style="color:red">(no details)</span></p>';
                list.prepend(item);
                setTimeout(removeTasks, 3);
            }
        }

        function updateTaskList() {
            const list = document.getElementById('todo-list');
            const currentTasks = list.querySelectorAll('.item-hidden');

            if (currentTasks.length === 0) {
                alert('There are no tasks to be added.');
                return;
            }

            const newItems = [];
            currentTasks.forEach(item => {
                const itemDiv = document.createElement('div');
                itemDiv.className = 'item-added';
                itemDiv.innerHTML = `<button onclick="updateTaskList()">Update List</button>` +
                       '<h2 style="color:red;">Task Summary</h2>' +
                       '<p style="color:green;">Completed (%): %</p>' +
                       '<p style="color:red;">Unknown (%): <span style="color:red">(no details)</span></p>`;
                newItems.push(itemDiv);
            });
            list.insertBefore(newItems.last, list.firstChild);
        }

        function removeTasks() {
            const list = document.getElementById('todo-list');
            if (!list.classList.contains('item-hidden')) {
                list.classList.remove('item-hidden');
            }
        }
    </script>
</body>
</html>
```
